const axios = require('axios'); // Assuming you'll use axios for Slack API interaction

/**
 * Posts a message to a specified Slack channel using the Slack API.
 *
 * @param {string} text - The message content to be posted.
 * @param {string} channelId - The ID of the Slack channel to send the message to.
 * @param {object} [slackToken] -  An object with a 'slackToken' property containing your verified Slack bot token (required for authentication).
 * @returns {Promise<object>} Resolves with the Slack API response data on success, rejects with an error on failure.
 */
async function postToSlack(text, channelId, slackToken) {
  if (!slackToken || !slackToken.slackToken) {
    return Promise.reject(new Error("Missing required 'slackToken.slackToken' for API authentication."));
  }

  const url = `https://slack.com/api/chat.postMessage`;
  const payload = {
    channel: channelId,
    text: text,
    // Add optional parameters like thread_ts, username (for bot persona), etc. as needed
  };

  try {
    const response = await axios.post(url, payload, {
      headers: {
        Authorization: `Bearer ${slackToken.slackToken}`, 
      },
    });
    return response.data; // Return Slack API's response object
  } catch (error) {
    console.error("Slack API Error:", error);
    return Promise.reject(error); // Handle and reject on API errors
  }
}

// Example Usage:
const mySlackToken = { slackToken: 'YOUR_ gerçek_SLACK_BOT_TOKEN' }; // Replace with your actual token
postToSlack("Hello from my JavaScript function!", "C123ABC456DEF", mySlackToken)
  .then(result => console.log("Slack API Response:", result))
  .catch(err => console.error("Posting error:", err));
```

